"""Pure stack-shape helpers for skill preconditions.

Frame lists in, frame lists out. Tracker mutation and activation stay on
``SkillExecutor``.
"""

from __future__ import annotations

from collections.abc import Sequence
from dataclasses import replace
from typing import Optional

from rasa.dialogue_understanding.stack.frames.dialogue_stack_frame import (
    DialogueStackFrame,
)
from rasa.dialogue_understanding.stack.frames.mantle_stack_frames import (
    MantleStackFrameType,
    OrderedBlockStackFrame,
    SkillStackFrame,
)

_LIVE_RESOLVER_FRAME_TYPES = frozenset(
    {
        MantleStackFrameType.REGULAR,
        MantleStackFrameType.CALL,
    }
)


def live_resolver_family_len(
    frames: Sequence[DialogueStackFrame], resolver_skill_id: str
) -> int:
    """Count contiguous live frames of *resolver_skill_id* from the top."""
    count = 0
    for frame in reversed(frames):
        if not isinstance(frame, (SkillStackFrame, OrderedBlockStackFrame)):
            break
        if frame.skill_id != resolver_skill_id:
            break
        if frame.frame_type not in _LIVE_RESOLVER_FRAME_TYPES:
            break
        count += 1
    return count


def split_live_resolver_family(
    frames: Sequence[DialogueStackFrame], resolver_skill_id: str
) -> tuple[list[DialogueStackFrame], list[DialogueStackFrame]]:
    """Split *frames* into ``(below, live resolver family from bottom to top)``."""
    family_len = live_resolver_family_len(frames, resolver_skill_id)
    frame_list = list(frames)
    if family_len == 0:
        return frame_list, []
    return frame_list[:-family_len], frame_list[-family_len:]


def promote_pending_consumer_frames(
    frames: Sequence[DialogueStackFrame], consumer_skill_id: str
) -> list[DialogueStackFrame]:
    """Turn PENDING frames of *consumer_skill_id* into their stored active type."""
    promoted: list[DialogueStackFrame] = []
    for frame in frames:
        if (
            isinstance(frame, (SkillStackFrame, OrderedBlockStackFrame))
            and frame.skill_id == consumer_skill_id
            and frame.frame_type == MantleStackFrameType.PENDING
        ):
            promoted.append(
                replace(
                    frame,
                    frame_type=(
                        frame.previous_frame_type or MantleStackFrameType.REGULAR
                    ),
                    previous_frame_type=None,
                )
            )
        else:
            promoted.append(frame)
    return promoted


def drop_skill_frames(
    frames: Sequence[DialogueStackFrame], skill_id: str
) -> list[DialogueStackFrame]:
    """Return *frames* without any skill or ordered-block frame for *skill_id*."""
    return [
        frame
        for frame in frames
        if not (
            isinstance(frame, (SkillStackFrame, OrderedBlockStackFrame))
            and frame.skill_id == skill_id
        )
    ]


def drop_top_pending_consumer(
    frames: Sequence[DialogueStackFrame],
) -> Optional[list[DialogueStackFrame]]:
    """Remove a top PENDING consumer, including its skill wrapper.

    Returns ``None`` when the top frame is not a pending consumer.
    """
    if not frames:
        return None
    new_frames = list(frames)
    top = new_frames[-1]
    if not isinstance(top, (SkillStackFrame, OrderedBlockStackFrame)):
        return None
    if top.frame_type != MantleStackFrameType.PENDING:
        return None
    if isinstance(top, OrderedBlockStackFrame):
        new_frames = [
            frame
            for frame in new_frames
            if not (
                isinstance(frame, SkillStackFrame) and frame.skill_id == top.skill_id
            )
        ]
    new_frames.pop()
    return new_frames


def pending_consumer_frame_ids_below(
    frames: Sequence[DialogueStackFrame], index: int
) -> frozenset[str]:
    """Return the ids of a pending consumer sitting directly below *index*.

    ``activate`` of a skill with an unmet precondition pushes the consumer as
    ``PENDING`` and its resolver on top. The consumer frames (the ``PENDING``
    frame and its same-skill wrapper) keep their ids when the resolver
    finishes and they are promoted. Older parked frames of that skill are not
    included.
    """
    below = index - 1
    if below < 0:
        return frozenset()
    frame = frames[below]
    if not (
        isinstance(frame, (SkillStackFrame, OrderedBlockStackFrame))
        and frame.frame_type == MantleStackFrameType.PENDING
    ):
        return frozenset()
    consumer_skill_id = frame.skill_id
    consumer_ids: set[str] = set()
    while below >= 0:
        frame = frames[below]
        if not (
            isinstance(frame, (SkillStackFrame, OrderedBlockStackFrame))
            and frame.skill_id == consumer_skill_id
            and frame.frame_type != MantleStackFrameType.INTERRUPT
        ):
            break
        consumer_ids.add(frame.frame_id)
        below -= 1
    return frozenset(consumer_ids)
